  9	import hotel.reservations.ReservationStore;
 10	import hotel.rooms.Rooms;
 11	import hotel.web.HttpApi;
 12	import io.javalin.Javalin;
 13	import javax.sql.DataSource;
 14	
 15	/** Puts the inn's pieces together and runs the HTTP server. */
 16	public final class Hotel {
 17	
 18	    private final Javalin server;
 19	
 20	    public Hotel(DataSource dataSource) {
 21	        Rooms rooms = new Rooms(dataSource);
 22	        ReservationStore store = new ReservationStore(dataSource);
 23	        SentMessages sentMessages = new SentMessages(dataSource);
 24	        ReservationService reservations =
 25	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
 26	        HttpApi api = new HttpApi(
 27	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
 28	        this.server = api.server();
 29	    }
 30	
 31	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
 32	    public int start(int port) {
 33	        server.start(port);
 34	        return server.port();
 35	    }
 36	
 37	    public void stop() {
 38	        server.stop();
 39	    }
 40	
 41	    public static void main(String[] args) {
 42	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 43	        Database database = new Database(System.getenv());
 44	        new Hotel(database.dataSource()).start(port);
 45	    }
 46	}
 55	
 56	    @Override
 57	    public String title() {
 58	        return "Fatura de hospedagem";
 59	    }
 60	
 61	    private BigDecimal calculateIss() {
 62	        return total.multiply(new BigDecimal("0.05")).setScale(2, java.math.RoundingMode.HALF_UP);
 63	    }
 64	
 65	    @Override
 66	    public String text() {
 67	        StringBuilder text = new StringBuilder();
 68	        text.append("Fatura de hospedagem nº ").append(reservationId).append('\n');
 69	        text.append("Empresa: ").append(companyName).append(" (CNPJ ").append(companyCnpj).append(")\n");
 70	        text.append("Hóspede: ").append(guestName).append("\n");
 71	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
 72	        text.append("Entrada: ").append(TextFormat.date(checkIn))
 73	                .append(" | Saída: ").append(TextFormat.date(checkOut))
 74	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
 75	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
 76	        if (discount.signum() > 0) {
 77	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
 78	        }
 79	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
 80	        BigDecimal iss = calculateIss();
 81	        text.append("ISS retido (5%): ").append(TextFormat.money(iss)).append('\n');
 82	        return text.toString();
 83	    }
 84	}

